const body = $json.body;
const conversationId = body.conversation && body.conversation.id;
const contactName = (body.sender && body.sender.name) || 'Unknown';
const contactPhone = (body.sender && body.sender.phone_number) || '';
const text = body.content || '';
const attachments = body.attachments || [];
const audioAttachment = attachments.find(function(a) { return a.file_type === 'audio'; });
const imageAttachment = attachments.find(function(a) { return a.file_type === 'image'; });
return [{
  json: {
    conversationId,
    contactName,
    contactPhone,
    text,
    hasAudio: audioAttachment ? 'true' : 'false',
    audioUrl: audioAttachment ? audioAttachment.data_url : null,
    hasImage: imageAttachment ? 'true' : 'false',
    imageUrl: imageAttachment ? imageAttachment.data_url : null
  }
}];

const item = $input.first().json;
const body = $('Chatwoot Webhook').first().json.body;

function sanitizeId(raw) {
  if (!raw) return null;
  const str = String(raw).trim();
  if (str.endsWith('@lid')) {
    const digits = str.slice(0, -4).replace(/[^0-9]/g, '');
    return digits ? { type: 'lid', key: 'lid_' + digits } : null;
  }
  const digits = str.replace(/[^0-9]/g, '');
  return digits.length >= 6 ? { type: 'phone', key: digits } : null;
}

let identity = sanitizeId(item.contactPhone);
if (!identity) {
  const fallbackRaw = (body.conversation && body.conversation.contact_inbox && body.conversation.contact_inbox.source_id)
    || (body.sender && body.sender.identifier)
    || ('cwcontact' + ((body.sender && body.sender.id) || item.conversationId));
  identity = sanitizeId(fallbackRaw) || { type: 'unresolved', key: 'unresolved_' + String(fallbackRaw).replace(/[^0-9a-zA-Z]/g, '') };
}

return [{ json: Object.assign({}, item, { memoryKey: identity.key, identityType: identity.type }) }];

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
const handoff = staticData.humanHandoff[item.conversationId];
const now = Date.now();
const THREE_HOURS = 3 * 60 * 60 * 1000;
const THREE_MIN = 3 * 60 * 1000;
if (handoff) {
  if (now - handoff.since >= THREE_HOURS) {
    delete staticData.humanHandoff[item.conversationId];
    return [{ json: item }];
  }
  const gap = now - (handoff.lastSeenAt || handoff.since);
  handoff.lastSeenAt = now;
  if (gap < THREE_MIN) {
    return [];
  }
  return [{ json: Object.assign({}, item, { alreadyHandedOff: 'true' }) }];
}
return [{ json: item }];

const orig = $('Extract Chatwoot Message').first().json;
const buffer = await helpers.getBinaryDataBuffer(0, 'data');
const audioBase64 = buffer.toString('base64');
return [{ json: Object.assign({}, orig, { audioBase64 }) }];

const orig = $('Extract Chatwoot Message').first().json;
const transcript = $json.results && $json.results[0] && $json.results[0].alternatives && $json.results[0].alternatives[0] && $json.results[0].alternatives[0].transcript || '';
return [{ json: Object.assign({}, orig, { text: transcript || "(customer sent a voice note that could not be transcribed)" }) }];

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.history) staticData.history = {};
const history = staticData.history[item.conversationId] || [];
return [{ json: Object.assign({}, item, { historyMessages: history.slice(-10) }) }];

const prev = $('Load Conversation History (CW)').first().json;
const identity = $('Resolve Customer Identity').first().json;
const memoryResult = $json;
let memoryText = '';
let isNewCustomer = true;
if (!memoryResult.error) {
  const buf = await helpers.getBinaryDataBuffer(0, 'memoryFile');
  memoryText = buf.toString('utf8');
  isNewCustomer = false;
}
return [{ json: Object.assign({}, prev, { memoryKey: identity.memoryKey, memoryText, isNewCustomer, firstContact: isNewCustomer ? 'true' : 'false' }) }];

const item = $input.first().json;
return [{
  json: {
    memoryKey: item.memoryKey,
    memoryText: item.memoryText,
    contactName: item.contactName,
    contactPhone: item.contactPhone,
    customerName: null,
    newFact: null,
    language: 'en',
    customerMessage: item.text,
    reply: 'Sent the welcome menu (Our AI Solutions / Get Pricing-Demo / Talk to a Human).'
  }
}];

const prev = $('Parse Customer Memory (CW)').first().json;
let parsed;
try {
  parsed = JSON.parse($json.choices?.[0]?.message?.content || '{}');
} catch (e) {
  parsed = {};
}
const reply = parsed.reply || "Sorry, I couldn't process that. Our team will follow up with you shortly.";
const wantsHuman = !!parsed.wants_human;
const summary = parsed.summary || '(no summary available)';
let language = ['en', 'zh', 'ms'].includes(parsed.language) ? parsed.language : 'en';
const hasCJK = /[\u4e00-\u9fff]/.test(reply);
if (hasCJK) {
  language = 'zh';
} else if (language === 'zh' && !hasCJK) {
  language = 'en';
}
const customerName = (parsed.customer_name && String(parsed.customer_name).trim()) || null;
const newFact = (parsed.new_fact && String(parsed.new_fact).trim()) || null;
const staticData = $getWorkflowStaticData('global');
if (!staticData.history) staticData.history = {};
if (!staticData.history[prev.conversationId]) staticData.history[prev.conversationId] = [];
staticData.history[prev.conversationId].push({ role: 'user', content: prev.text });
staticData.history[prev.conversationId].push({ role: 'assistant', content: reply });
if (staticData.history[prev.conversationId].length > 20) {
  staticData.history[prev.conversationId] = staticData.history[prev.conversationId].slice(-20);
}
if (wantsHuman) {
  if (!staticData.humanHandoff) staticData.humanHandoff = {};
  staticData.humanHandoff[prev.conversationId] = { since: Date.now(), lastSeenAt: Date.now() };
}
return [{
  json: {
    conversationId: prev.conversationId,
    contactName: prev.contactName,
    contactPhone: prev.contactPhone,
    customerMessage: prev.text,
    reply,
    wantsHuman: wantsHuman ? 'true' : 'false',
    summary,
    language,
    hasAudio: prev.hasAudio,
    memoryKey: prev.memoryKey,
    memoryText: prev.memoryText,
    isNewCustomer: prev.isNewCustomer,
    customerName,
    newFact
  }
}];

const buf = Buffer.from($json.audioContent, 'base64');
const bin = await helpers.prepareBinaryData(buf, 'reply.mp3', 'audio/mpeg');
const prev = $('Format Reply (CW)').first().json;
return [{ json: { conversationId: prev.conversationId }, binary: { data: bin } }];

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.conversations) staticData.conversations = {};
const key = item.conversationId;
if (!staticData.conversations[key]) {
  staticData.conversations[key] = { messages: [], name: item.contactName, phone: item.contactPhone };
}
staticData.conversations[key].messages.push({
  customerMessage: item.customerMessage,
  reply: item.reply,
  summary: item.summary,
  wantsHuman: item.wantsHuman
});
staticData.conversations[key].name = item.contactName;
staticData.conversations[key].phone = item.contactPhone;
staticData.conversations[key].lastMessageAt = Date.now();
return [{ json: { conversationId: key } }];

const item = $input.first().json;
const now = new Date().toISOString();

const existing = item.memoryText || '';
let name = item.customerName || null;
if (!name) {
  const m = existing.match(/^Name:\s*(.+)$/m);
  if (m) name = m[1].trim();
}
if (!name && item.contactName && item.contactName !== 'Unknown') name = item.contactName;

let facts = [];
const factsBlock = existing.split('## Facts')[1];
if (factsBlock) {
  const beforeNextHeading = factsBlock.split('## Conversation Log')[0];
  facts = beforeNextHeading.split('\n').map(function(l) { return l.trim(); }).filter(function(l) { return l.indexOf('- ') === 0; }).map(function(l) { return l.slice(2).trim(); });
}
if (item.newFact && facts.indexOf(item.newFact) === -1) facts.push(item.newFact);
if (facts.length > 30) facts = facts.slice(-30);

let logLines = [];
const logBlock = existing.split('## Conversation Log')[1];
if (logBlock) {
  logLines = logBlock.trim().split('\n').filter(function(l) { return l.length > 0; });
}
logLines.push('- [' + now + '] Asked: ' + item.customerMessage + ' -> Replied: ' + item.reply);
if (logLines.length > 15) logLines = logLines.slice(-15);

const phoneLine = item.memoryKey && /^[0-9]+$/.test(item.memoryKey) ? item.memoryKey : (item.contactPhone || 'unresolved');

const factsText = facts.length ? facts.map(function(f) { return '- ' + f; }).join('\n') : '- (none yet)';
const md = '# Customer Memory\n\nName: ' + (name || 'Unknown') + '\nPhone: ' + phoneLine + '\nPreferred language: ' + item.language + '\nLast contact: ' + now + '\n\n## Facts\n' + factsText + '\n\n## Conversation Log\n' + logLines.join('\n') + '\n';

return [{ json: { memoryKey: item.memoryKey, memoryMarkdown: md } }];

const item = $input.first().json;
const buf = Buffer.from(item.memoryMarkdown, 'utf8');
const bin = await helpers.prepareBinaryData(buf, item.memoryKey + '.md', 'text/markdown');
return [{ json: { memoryKey: item.memoryKey }, binary: { data: bin } }];

const staticData = $getWorkflowStaticData('global');
const conversations = staticData.conversations || {};
const now = Date.now();
const idleMs = 3 * 60 * 1000;
const results = [];
for (const key of Object.keys(conversations)) {
  const convo = conversations[key];
  if (!convo.messages || convo.messages.length === 0) continue;
  if (now - (convo.lastMessageAt || 0) >= idleMs) {
    const name = convo.name || 'Unknown';
    const phone = convo.phone || '';
    const msgs = convo.messages;
    const wantsHuman = msgs.some(function(m) { return m.wantsHuman === 'true' || m.wantsHuman === true; });
    const lines = msgs.map(function(m, i) {
      return (i + 1) + '. Customer: ' + m.customerMessage + '\n   AI reply: ' + m.reply + '\n   Summary: ' + m.summary;
    }).join('\n\n');
    results.push({ json: { to: phone, name: name, wantsHuman: wantsHuman, conversationText: lines, exchangeCount: msgs.length } });
    delete staticData.conversations[key];
  }
}
return results;
